1	//! [`AgentServer`] — shared app state, builder, router factory, and listener helpers.
2	
3	use std::{collections::HashMap, sync::Arc, time::Duration};
4	
5	use axum::{
6	    extract::{Request, State},
7	    middleware::Next,
8	    response::Response,
9	    routing::{get, post},
10	    Router,
11	};
12	use paigasus_helikon_core::{Agent, RunConfig, Runner};
13	use paigasus_helikon_runtime_tokio::TokioRunner;
14	
15	use crate::{
16	    auth::AuthLayer,
17	    context::{ContextProvider, DefaultContextProvider},
18	    error::ServerError,
19	    handlers,
20	    registry::RunRegistry,
21	    session::{InMemorySessionProvider, SessionLocks, SessionProvider},
22	};
23	
24	// ── AppState ──────────────────────────────────────────────────────────────────
25	
26	/// Inner shared state; allocated once and reference-counted.
27	pub(crate) struct AppStateInner<Ctx> {
28	    /// In-flight and recently-completed run registry.
29	    pub registry: Arc<RunRegistry>,
30	    /// Execution backend used by the run handlers.
31	    pub runner: Arc<dyn Runner<Ctx>>,
32	    /// Mounted agents, keyed by [`paigasus_helikon_core::Agent::name`].
33	    pub agents: HashMap<String, Arc<dyn Agent<Ctx>>>,
34	    /// Session store.
35	    pub sessions: Arc<dyn SessionProvider>,
36	    /// Per-request context builder.
37	    pub context: Arc<dyn ContextProvider<Ctx>>,
38	    /// Optional request authentication gate.
39	    pub auth: Option<Arc<dyn AuthLayer>>,
40	    /// Default run configuration applied to every run.
41	    pub run_config: RunConfig,
42	    /// Per-session run serialisation locks.
43	    pub locks: SessionLocks,
44	}
45	
46	/// Cheaply-cloneable axum extraction state.
47	///
48	/// All handler tasks share a single [`AppStateInner<Ctx>`] through this wrapper.
49	/// Cloning is an [`Arc`] increment, not a deep copy.
50	pub(crate) struct AppState<Ctx> {
51	    inner: Arc<AppStateInner<Ctx>>,
52	}
53	
54	impl<Ctx> Clone for AppState<Ctx> {
55	    fn clone(&self) -> Self {
56	        Self {
57	            inner: Arc::clone(&self.inner),
58	        }
59	    }
60	}
61	
62	impl<Ctx> std::ops::Deref for AppState<Ctx> {
63	    type Target = AppStateInner<Ctx>;
64	
65	    fn deref(&self) -> &Self::Target {
66	        &self.inner
67	    }
68	}
69	
70	// ── AgentServerBuilder ────────────────────────────────────────────────────────
71	
72	/// Builder for [`AgentServer`].
73	///
74	/// Obtain via [`AgentServer::builder`].  All setters consume and return `Self`
75	/// for chaining.  Call [`build`](AgentServerBuilder::build) once all agents and
76	/// optional overrides have been supplied.
77	pub struct AgentServerBuilder<Ctx> {
78	    agents: HashMap<String, Arc<dyn Agent<Ctx>>>,
79	    /// Non-`None` when a duplicate agent name was detected; surfaced by `build()`.
80	    dup_error: Option<String>,
81	    runner: Option<Arc<dyn Runner<Ctx>>>,
82	    sessions: Option<Arc<dyn SessionProvider>>,
83	    context: Option<Arc<dyn ContextProvider<Ctx>>>,
84	    auth: Option<Arc<dyn AuthLayer>>,
85	    run_config: RunConfig,
86	    max_sessions: usize,
87	    retention: Duration,
88	    max_runs: usize,
89	    max_events_per_run: usize,
90	}
91	
92	impl<Ctx: Send + Sync + 'static> AgentServerBuilder<Ctx> {
93	    fn new() -> Self {
94	        Self {
95	            agents: HashMap::new(),
96	            dup_error: None,
97	            runner: None,
98	            sessions: None,
99	            context: None,
100	            auth: None,
101	            run_config: RunConfig::default(),
102	            max_sessions: 4096,
103	            retention: Duration::from_secs(300),
104	            max_runs: 1024,
105	            max_events_per_run: 10_000,
106	        }
107	    }
108	
109	    /// Register an [`Agent`].
110	    ///
111	    /// If an agent with the same [`name`](paigasus_helikon_core::Agent::name) has already been
112	    /// registered, the duplicate is silently dropped and an error is queued; [`build`] will
113	    /// return that error.
114	    ///
115	    /// [`build`]: AgentServerBuilder::build
116	    pub fn agent(mut self, agent: Arc<dyn Agent<Ctx>>) -> Self {
117	        use std::collections::hash_map::Entry;
118	        let name = agent.name().to_owned();
119	        match self.agents.entry(name) {
120	            Entry::Occupied(e) => {
121	                self.dup_error = Some(e.key().clone());
122	            }
123	            Entry::Vacant(e) => {
124	                e.insert(agent);
125	            }
126	        }
127	        self
128	    }
129	
130	    /// Override the execution backend. Defaults to [`TokioRunner`].
131	    pub fn runner(mut self, runner: Arc<dyn Runner<Ctx>>) -> Self {
132	        self.runner = Some(runner);
133	        self
134	    }
135	
136	    /// Override the session provider. Defaults to an [`InMemorySessionProvider`] with
137	    /// `max_sessions` capacity.
138	    pub fn session_provider(mut self, provider: Arc<dyn SessionProvider>) -> Self {
139	        self.sessions = Some(provider);
140	        self
141	    }
142	
143	    /// Set the context provider.
144	    ///
145	    /// Required unless [`with_default_context`](AgentServerBuilder::with_default_context) is
146	    /// called (which is only available when `Ctx: Default`).  [`build`] returns
147	    /// [`ServerError::Internal`] if neither is invoked.
148	    ///
149	    /// [`build`]: AgentServerBuilder::build
150	    pub fn context_provider(mut self, provider: Arc<dyn ContextProvider<Ctx>>) -> Self {
151	        self.context = Some(provider);
152	        self
153	    }
154	
155	    /// Set an authentication layer.  If unset, all requests are admitted without authentication.
156	    pub fn auth(mut self, auth: Arc<dyn AuthLayer>) -> Self {
157	        self.auth = Some(auth);
158	        self
159	    }
160	
161	    /// Override the per-run configuration applied to every agent run.
162	    pub fn run_config(mut self, config: RunConfig) -> Self {
163	        self.run_config = config;
164	        self
165	    }
166	
167	    /// Set how long completed runs are retained in the registry. Default: 5 minutes.
168	    pub fn run_retention(mut self, duration: Duration) -> Self {
169	        self.retention = duration;
170	        self
171	    }
172	
173	    /// Cap the number of retained completed runs. Oldest-completed runs are evicted
174	    /// when the cap is exceeded. Default: 1 024.
175	    pub fn max_retained_runs(mut self, max: usize) -> Self {
176	        self.max_runs = max;
177	        self
178	    }
179	
180	    /// Cap the number of tracked in-memory sessions. Default: 4 096.
181	    pub fn max_sessions(mut self, max: usize) -> Self {
182	        self.max_sessions = max;
183	        self
184	    }
185	
186	    /// Build an [`AgentServer`].
187	    ///
188	    /// # Errors
189	    ///
190	    /// - [`ServerError::BadRequest`] — a duplicate agent name was registered.
191	    /// - [`ServerError::Internal`] — no context provider was supplied (either via
192	    ///   [`context_provider`](AgentServerBuilder::context_provider) or
193	    ///   [`with_default_context`](AgentServerBuilder::with_default_context)).
194	    pub fn build(self) -> Result<AgentServer<Ctx>, ServerError> {
195	        if let Some(name) = self.dup_error {
196	            return Err(ServerError::BadRequest(format!(
197	                "duplicate agent name: {name}"
198	            )));
199	        }
200	
201	        // Reject a zero-capacity in-memory session store *before* constructing
202	        // it: `InMemorySessionProvider::new(0)` asserts and would panic. A
203	        // custom session provider sidesteps this since `max_sessions` is unused.
204	        if self.sessions.is_none() && self.max_sessions == 0 {
205	            return Err(ServerError::BadRequest(
206	                "max_sessions must be greater than 0".to_owned(),
207	            ));
208	        }
209	
210	        let context = self.context.ok_or_else(|| {
211	            ServerError::Internal(
212	                "no context provider set; call `.context_provider(…)` or \
213	                 `.with_default_context()` (requires Ctx: Default)"
214	                    .to_owned(),
215	            )
216	        })?;
217	
218	        let runner: Arc<dyn Runner<Ctx>> = self.runner.unwrap_or_else(|| Arc::new(TokioRunner));
219	
220	        let sessions: Arc<dyn SessionProvider> = self
221	            .sessions
222	            .unwrap_or_else(|| Arc::new(InMemorySessionProvider::new(self.max_sessions)));
223	
224	        let registry = RunRegistry::new(self.retention, self.max_runs, self.max_events_per_run);
225	
226	        let state = AppState {
227	            inner: Arc::new(AppStateInner {
228	                registry,
229	                runner,
230	                agents: self.agents,
231	                sessions,
232	                context,
233	                auth: self.auth,
234	                run_config: self.run_config,
235	                locks: SessionLocks::new(),
236	            }),
237	        };
238	
239	        Ok(AgentServer { state })
240	    }
241	}
