255	// ── AgentServer ───────────────────────────────────────────────────────────────
256	
257	/// Self-hosted HTTP server that mounts one or more [`Agent`]s on an axum router.
258	///
259	/// # Quick start
260	///
261	/// ```ignore
262	/// # use std::sync::Arc;
263	/// # use paigasus_helikon_runtime_axum::AgentServer;
264	/// # async fn run() -> Result<(), Box<dyn std::error::Error>> {
265	/// let server = AgentServer::<()>::builder()
266	///     .with_default_context()
267	///     .agent(Arc::new(my_agent))
268	///     .build()?;
269	///
270	/// server.serve("0.0.0.0:8080").await?;
271	/// # Ok(())
272	/// # }
273	/// ```
274	pub struct AgentServer<Ctx> {
275	    state: AppState<Ctx>,
276	}
277	
278	impl<Ctx: Send + Sync + 'static> AgentServer<Ctx> {
279	    /// Return a new builder.
280	    pub fn builder() -> AgentServerBuilder<Ctx> {
281	        AgentServerBuilder::new()
282	    }
283	
284	    /// Build the axum [`Router`].
285	    ///
286	    /// Pure: spawns nothing.  Suitable for embedding into a larger router or for
287	    /// testing with axum's `Router::oneshot`.
288	    ///
289	    /// When an [`AuthLayer`] is configured the whole router is wrapped in a
290	    /// request-level authentication middleware, so **every** route — including
291	    /// `GET /agents`, `GET /openapi.json`, and the WebSocket events endpoint —
292	    /// is gated, not just the run-creation handler.
293	    pub fn router(&self) -> Router {
294	        let router = Router::new()
295	            .route("/agents", get(handlers::agents::list::<Ctx>))
296	            .route(
297	                "/agents/{name}/runs",
298	                post(handlers::runs::create_run::<Ctx>),
299	            )
300	            .route(
301	                "/agents/{name}/runs/{id}/events",
302	                get(handlers::events::events::<Ctx>),
303	            );
304	
305	        #[cfg(feature = "openapi")]
306	        let router = router.route("/openapi.json", get(handlers::openapi::openapi_json::<Ctx>));
307	
308	        let router = router.with_state(self.state.clone());
309	
310	        // Gate every route behind the auth layer (if configured). The middleware
311	        // carries its own state clone, so it is applied after `with_state`.
312	        if self.state.auth.is_some() {
313	            router.layer(axum::middleware::from_fn_with_state(
314	                self.state.clone(),
315	                auth_middleware::<Ctx>,
316	            ))
317	        } else {
318	            router
319	        }
320	    }
321	
322	    /// Start serving on `listener`.
323	    ///
324	    /// Spawns the run-registry sweeper background task, then drives the axum
325	    /// serve loop until it exits.
326	    ///
327	    /// # Errors
328	    ///
329	    /// Returns [`ServerError::Internal`] if the serve loop returns an error.
330	    pub async fn serve_with_listener(
331	        self,
332	        listener: tokio::net::TcpListener,
333	    ) -> Result<(), ServerError> {
334	        self.state.registry.spawn_sweeper();
335	        axum::serve(listener, self.router())
336	            .await
337	            .map_err(|e| ServerError::Internal(e.to_string()))
338	    }
339	
340	    /// Bind `addr` and start serving.
341	    ///
342	    /// Convenience wrapper around [`serve_with_listener`](AgentServer::serve_with_listener).
343	    ///
344	    /// # Errors
345	    ///
346	    /// Returns [`ServerError::Internal`] if binding or serving fails.
347	    pub async fn serve(self, addr: impl tokio::net::ToSocketAddrs) -> Result<(), ServerError> {
348	        let listener = tokio::net::TcpListener::bind(addr)
349	            .await
350	            .map_err(|e| ServerError::Internal(e.to_string()))?;
351	        self.serve_with_listener(listener).await
352	    }
353	}
354	
355	// ── auth middleware ─────────────────────────────────────────────────────────────
356	
357	/// Router-level authentication gate.
358	///
359	/// Installed by [`AgentServer::router`] only when an [`AuthLayer`] is configured.
360	/// Runs before any route handler, so every endpoint is authenticated uniformly.
361	/// On success the request is reassembled from its parts so that any identity the
362	/// auth layer inserted into `parts.extensions` flows downstream to the
363	/// [`ContextProvider`].
364	async fn auth_middleware<Ctx: Send + Sync + 'static>(
365	    State(state): State<AppState<Ctx>>,
366	    req: Request,
367	    next: Next,
368	) -> Result<Response, ServerError> {
369	    if let Some(auth) = &state.auth {
370	        let (mut parts, body) = req.into_parts();
371	        auth.authenticate(&mut parts).await?;
372	        // Reassemble so identity values placed into `parts.extensions` survive.
373	        let req = Request::from_parts(parts, body);
374	        Ok(next.run(req).await)
375	    } else {
376	        Ok(next.run(req).await)
377	    }
378	}
