62	/// Upper bound on the request body we will buffer before deserializing (2 MiB).
63	const MAX_BODY_BYTES: usize = 2 * 1024 * 1024;
64	
65	/// Query parameters selecting the response transport.
66	#[derive(Debug, Default, Deserialize)]
67	pub(crate) struct RunQuery {
68	    /// `sse` selects the Server-Sent-Events transport.
69	    #[serde(default)]
70	    stream: Option<String>,
71	    /// `async` detaches the run and returns `202 Accepted` immediately.
72	    #[serde(default)]
73	    mode: Option<String>,
74	}
75	
76	impl RunQuery {
77	    /// `true` when the caller requested the detached (`?mode=async`) transport.
78	    fn is_async(&self) -> bool {
79	        self.mode.as_deref() == Some("async")
80	    }
81	
82	    /// `true` when the caller requested the SSE (`?stream=sse`) transport.
83	    fn is_sse(&self) -> bool {
84	        self.stream.as_deref() == Some("sse")
85	    }
86	
87	    /// Reject unrecognised or mutually-exclusive transport selectors.
88	    ///
89	    /// Without this an unknown `?mode=`/`?stream=` value would silently fall
90	    /// back to one-shot, and `?mode=async&stream=sse` would silently prefer
91	    /// async — both surprising the caller. Each is surfaced as a 400 instead.
92	    ///
93	    /// # Errors
94	    ///
95	    /// [`ServerError::BadRequest`] if `mode` is set to anything other than
96	    /// `async`, if `stream` is set to anything other than `sse`, or if both the
97	    /// async and SSE transports are requested together.
98	    fn validate(&self) -> Result<(), ServerError> {
99	        if let Some(mode) = self.mode.as_deref() {
100	            if mode != "async" {
101	                return Err(ServerError::BadRequest(format!(
102	                    "invalid `mode` selector `{mode}`; the only supported value is `async`"
103	                )));
104	            }
105	        }
106	        if let Some(stream) = self.stream.as_deref() {
107	            if stream != "sse" {
108	                return Err(ServerError::BadRequest(format!(
109	                    "invalid `stream` selector `{stream}`; the only supported value is `sse`"
110	                )));
111	            }
112	        }
113	        if self.is_async() && self.is_sse() {
114	            return Err(ServerError::BadRequest(
115	                "`mode=async` and `stream=sse` are mutually exclusive".to_owned(),
116	            ));
117	        }
118	        Ok(())
119	    }
120	}
