122	/// `POST /agents/{name}/runs` — start a run of the named agent.
123	///
124	/// See the [module docs](self) for the execution model and the meaning of the
125	/// `?stream=` / `?mode=` query parameters.
126	///
127	/// # Errors
128	///
129	/// - [`ServerError::UnknownAgent`] (404) — no agent with `name` is registered.
130	/// - [`ServerError::Unauthorized`] (401/403) — the context provider rejected the
131	///   request's credentials. (The configured [`AuthLayer`](crate::AuthLayer) runs
132	///   earlier, as router-level middleware.)
133	/// - [`ServerError::BadRequest`] (400) — an invalid or conflicting `?stream=` /
134	///   `?mode=` selector, the body was not valid JSON for a [`RunRequest`], or an
135	///   explicit non-JSON content type was supplied.
136	/// - [`ServerError::RunStart`] (500) — the run failed before emitting any event
137	///   (one-shot mode only).
138	pub(crate) async fn create_run<Ctx: Send + Sync + 'static>(
139	    State(state): State<AppState<Ctx>>,
140	    Path(name): Path<String>,
141	    Query(query): Query<RunQuery>,
142	    request: Request,
143	) -> Result<Response, ServerError> {
144	    // 0. Reject invalid / conflicting transport selectors (400) before doing
145	    //    any work.
146	    query.validate()?;
147	
148	    // Split into parts + body up front; the body is consumed last. Auth has
149	    // already run as router-level middleware, so any identity it inserted is
150	    // present in `parts.extensions` for the context provider below.
151	    let (parts, body) = request.into_parts();
152	
153	    // 1. Resolve the agent (404 if unknown).
154	    let agent = state
155	        .agents
156	        .get(&name)
157	        .cloned()
158	        .ok_or_else(|| ServerError::UnknownAgent(name.clone()))?;
159	
160	    // 2. Deserialize the JSON body (400 on a bad body / non-JSON content type).
161	    let input = read_run_request(&parts, body).await?.into_agent_input();
162	
163	    // 3. Resolve the session from the optional `X-Session-Id` header.
164	    let session_id: Option<String> = parts
165	        .headers
166	        .get("x-session-id")
167	        .and_then(|v| v.to_str().ok())
168	        .map(str::to_owned);
169	    let session = state.sessions.session(session_id.as_deref()).await?;
170	
171	    // 4. Acquire the per-session serialization lock BEFORE creating/spawning the
172	    //    run so that same-session requests queue. The owned guard is moved into
173	    //    the writer task and released when the run completes.
174	    let guard: OwnedMutexGuard<()> = state
175	        .locks
176	        .lock_for(session_id.as_deref())
177	        .lock_owned()
178	        .await;
179	
180	    // 5. Build the run context, then register the run. Building the context
181	    //    before registering avoids leaking a never-terminal registry entry if
182	    //    the context provider fails.
183	    let cancel = CancellationToken::new();
184	    let ctx = state.context.build(&parts, session, cancel.clone()).await?;
185	    let (run_id, handle) = state.registry.create(name, cancel);
186	
187	    // 6. Spawn the writer task: drive the agent and drain its events into the log.
188	    spawn_writer(
189	        Arc::clone(&state.runner),
190	        agent,
191	        ctx,
192	        input,
193	        state.run_config.clone(),
194	        Arc::clone(&handle),
195	        Arc::clone(&state.registry),
196	        run_id,
197	        guard,
198	    );
199	
200	    // 7. Respond per the requested transport.
201	    if query.is_async() {
202	        return Ok(async_response(run_id));
203	    }
204	    if query.is_sse() {
205	        return Ok(sse_response(run_id, &handle));
206	    }
207	    oneshot_response(run_id, &handle).await
208	}
209	
210	/// Read and validate the JSON request body into a [`RunRequest`].
211	///
212	/// Performs a lightweight content-type check: returns 400 on an explicit
213	/// non-JSON content type, while a missing content type is tolerated and the
214	/// bytes are parsed optimistically.
215	async fn read_run_request(parts: &Parts, body: Body) -> Result<RunRequest, ServerError> {
216	    if let Some(ct) = parts
217	        .headers
218	        .get(CONTENT_TYPE)
219	        .and_then(|v| v.to_str().ok())
220	    {
221	        // Media types are case-insensitive (RFC 9110 §8.3.1), so `Application/JSON`
222	        // must be accepted exactly like `application/json`.
223	        let mime = ct
224	            .split(';')
225	            .next()
226	            .unwrap_or("")
227	            .trim()
228	            .to_ascii_lowercase();
229	        let is_json = mime == "application/json"
230	            || (mime.starts_with("application/") && mime.ends_with("+json"));
231	        if !is_json {
232	            return Err(ServerError::BadRequest(format!(
233	                "unsupported content type `{mime}`; expected application/json"
234	            )));
235	        }
236	    }
237	
238	    let bytes = axum::body::to_bytes(body, MAX_BODY_BYTES)
239	        .await
240	        .map_err(|e| ServerError::BadRequest(format!("failed to read request body: {e}")))?;
241	
242	    serde_json::from_slice::<RunRequest>(&bytes)
243	        .map_err(|e| ServerError::BadRequest(format!("invalid run request body: {e}")))
244	}
245	
246	/// Drop-guard that records a run's terminal bookkeeping exactly once — on the
247	/// normal path **and** on a panic unwind of the writer task.
248	///
249	/// Both operations are idempotent: [`EventLog::mark_terminal`] just sets a flag,
250	/// and [`RunRegistry::note_terminal`] only stamps when `terminal_at` is still
251	/// `None`. Without this guard a panic mid-drain (e.g. a faulty agent stream)
252	/// would strand every subscriber waiting forever.
253	struct TerminalGuard {
254	    log: Arc<EventLog>,
255	    registry: Arc<RunRegistry>,
256	    run_id: Uuid,
257	}
258	
259	impl Drop for TerminalGuard {
260	    fn drop(&mut self) {
261	        self.log.mark_terminal();
262	        self.registry.note_terminal(self.run_id, Instant::now());
263	    }
264	}
265	
266	/// Spawn the detached writer task that drives one run to completion.
267	///
268	/// Owns every input by value so the task satisfies `'static`. Holds the session
269	/// lock `guard` for the whole run and drops it (releasing the lock) once the run
270	/// is terminal and recorded in the registry. Terminal bookkeeping is owned by a
271	/// [`TerminalGuard`] so it still happens if the agent stream panics mid-drain.
272	#[allow(clippy::too_many_arguments)]
273	fn spawn_writer<Ctx: Send + Sync + 'static>(
274	    runner: Arc<dyn Runner<Ctx>>,
275	    agent: Arc<dyn Agent<Ctx>>,
276	    ctx: RunContext<Ctx>,
277	    input: AgentInput,
278	    run_config: RunConfig,
279	    handle: Arc<RunHandle>,
280	    registry: Arc<RunRegistry>,
281	    run_id: Uuid,
282	    guard: OwnedMutexGuard<()>,
283	) {
284	    tokio::spawn(async move {
285	        // Declared FIRST so it drops LAST: terminal bookkeeping (below) runs
286	        // before the session lock is released, preserving the original ordering.
287	        let _session_lock = guard;
288	        // Declared AFTER the lock so it drops FIRST. Its `Drop` marks the log
289	        // terminal and stamps the registry — even on a panic unwind.
290	        let _terminal = TerminalGuard {
291	            log: Arc::clone(&handle.log),
292	            registry,
293	            run_id,
294	        };
295	
296	        match runner
297	            .run_streamed(agent.as_ref(), ctx, input, run_config)
298	            .await
299	        {
300	            Ok(streaming) => {
301	                let mut events = streaming.events;
302	                while let Some(ev) = events.next().await {
303	                    handle.log.append(ev);
304	                }
305	                // Terminal marking is handled by `_terminal` on scope exit; a
306	                // real `RunCompleted`/`RunFailed` already set the flag, and the
307	                // guard's `mark_terminal` is an idempotent safety net otherwise.
308	            }
309	            Err(e) => {
310	                // The run failed to *start* (no events were ever emitted). Record
311	                // the cause; `_terminal` marks the log terminal so subscribers
312	                // unblock.
313	                *handle
314	                    .start_error
315	                    .lock()
316	                    .expect("start_error mutex poisoned") = Some(e.to_string());
317	            }
318	        }
319	    });
320	}
321	
322	/// Build the `202 Accepted` body for a detached run.
323	fn async_response(run_id: Uuid) -> Response {
324	    (
325	        StatusCode::ACCEPTED,
326	        Json(AsyncAccepted {
327	            run_id: run_id.to_string(),
328	        }),
329	    )
330	        .into_response()
331	}
332	
333	/// Unfold state for the SSE response stream: the live event stream, the cancel
334	/// drop-guard (held for the stream's whole lifetime so a client disconnect
335	/// cancels the run), a clone of the run handle (to synthesize a terminal frame
336	/// on a terminal-less close), and the `saw_terminal` / `done` flags.
337	struct SseState<S> {
338	    events: S,
339	    // Held only for its `Drop` side effect (cancels the run when the SSE
340	    // response — and with it this state — is dropped); never read directly.
341	    #[allow(dead_code)]
342	    disconnect: DropGuard,
343	    handle: Arc<RunHandle>,
344	    saw_terminal: bool,
345	    done: bool,
346	}
347	
348	/// Build the SSE streaming response.
349	///
350	/// The run's cancel `DropGuard` is folded into the stream state so that dropping
351	/// the response (a client disconnect) cancels the run. If the live event stream
352	/// ends without delivering a real terminal event (a start-error, or a stream
353	/// that ended/panicked mid-run), exactly one synthetic `run_failed` frame is
354	/// appended before the SSE stream closes — see
355	/// [`RunHandle::synthetic_terminal_frame`].
356	fn sse_response(run_id: Uuid, handle: &Arc<RunHandle>) -> Response {
357	    let disconnect = handle.cancel.clone().drop_guard();
358	    let events = handle.log.subscribe(0);
359	    let handle = Arc::clone(handle);
360	
361	    let stream = futures_util::stream::unfold(
362	        SseState {
363	            events,
364	            disconnect,
365	            handle,
366	            saw_terminal: false,
367	            done: false,
368	        },
369	        |mut state| async move {
370	            if state.done {
371	                return None;
372	            }
373	            match state.events.next().await {
374	                Some(ev) => {
375	                    state.saw_terminal |= is_terminal(&ev);
376	                    let frame = to_sse_event(&ev);
377	                    Some((Ok::<Event, Infallible>(frame), state))
378	                }
379	                None => {
380	                    // Live stream ended. If no real terminal was delivered, emit
381	                    // exactly one synthetic `run_failed` frame, then finish.
382	                    let synthetic = state.handle.synthetic_terminal_frame(state.saw_terminal)?;
383	                    let frame = to_sse_event(&synthetic);
384	                    state.done = true;
385	                    Some((Ok::<Event, Infallible>(frame), state))
386	                }
387	            }
388	        },
389	    );
390	
391	    let mut response = Sse::new(stream).into_response();
392	    insert_run_id(response.headers_mut(), run_id);
393	    response
394	}
395	
396	/// Build the one-shot response: subscribe, drain to the terminal event, then
397	/// aggregate into a [`RunResponse`].
398	async fn oneshot_response(run_id: Uuid, handle: &Arc<RunHandle>) -> Result<Response, ServerError> {
399	    // Cancel the run if the client disconnects while we await the result.
400	    let _disconnect = handle.cancel.clone().drop_guard();
401	
402	    // NOTE: the event log is capped at `max_events_per_run` events; `output`
403	    // in the response reflects only the events retained by the ring buffer.
404	    let events: Vec<AgentEvent> = handle.log.subscribe(0).collect().await;
405	
406	    // If the run failed to *start*, surface a 500 rather than a 200 envelope.
407	    if let Some(msg) = handle
408	        .start_error
409	        .lock()
410	        .expect("start_error mutex poisoned")
411	        .clone()
412	    {
413	        return Err(ServerError::RunStart(msg));
414	    }
415	
416	    let mut response = Json(RunResponse::from_events(run_id, events)).into_response();
417	    insert_run_id(response.headers_mut(), run_id);
418	    Ok(response)
419	}
420	
421	/// Serialize an [`AgentEvent`] into an SSE [`Event`], tagging the SSE `event:`
422	/// field with the event's serde `type` discriminant and carrying the full event
423	/// JSON as the `data:` payload.
424	fn to_sse_event(ev: &AgentEvent) -> Event {
425	    let value = serde_json::to_value(ev).expect("AgentEvent serializes");
426	    let event = match value.get("type").and_then(serde_json::Value::as_str) {
427	        Some(tag) => Event::default().event(tag),
428	        None => Event::default(),
429	    };
430	    event
431	        .json_data(&value)
432	        .expect("serde_json::Value serializes without error")
433	}
434	
435	/// Insert the `X-Run-Id` response header.
436	fn insert_run_id(headers: &mut HeaderMap, run_id: Uuid) {
437	    let value =
438	        HeaderValue::from_str(&run_id.to_string()).expect("uuid is always a valid header value");
439	    headers.insert("x-run-id", value);
440	}
