1	//! Cross-runtime HTTP wire-format conformance.
2	//!
3	//! Boots the `paigasus-helikon-runtime-axum` and `paigasus-helikon-runtime-actix`
4	//! servers with the SAME [`scripted_agents`] set and asserts that every
5	//! user-facing HTTP surface matches between the two runtimes — byte-identical
6	//! where the wire format is fully determined, structurally equal where a field
7	//! is legitimately per-run (a `run_id`) or order-nondeterministic (a HashMap of
8	//! agents).
9	//!
10	//! The two servers are booted with the two different runtime models on purpose:
11	//! axum via `tokio::spawn` on the test's own runtime; actix via a dedicated OS
12	//! thread driving its own `actix_web::rt::System`.
13	
14	use paigasus_helikon_runtime_http_conformance::scripted_agents;
15	
16	/// A fixed token substituted for the per-run UUID before a byte comparison.
17	const RUN_ID_TOKEN: &str = "<RUN_ID>";
18	
19	/// Boot the axum runtime on an ephemeral loopback port and return its base URL.
20	///
21	/// The serve loop is spawned as a task on the caller's tokio runtime, matching
22	/// the axum runtime's documented embedding model.
23	async fn boot_axum() -> String {
24	    let mut builder =
25	        paigasus_helikon_runtime_axum::AgentServer::<()>::builder().with_default_context();
26	    for agent in scripted_agents() {
27	        builder = builder.agent(agent);
28	    }
29	    let server = builder.build().expect("axum server builds");
30	
31	    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
32	        .await
33	        .expect("bind ephemeral port");
34	    let addr = listener.local_addr().expect("local addr");
35	    tokio::spawn(async move {
36	        server
37	            .serve_with_listener(listener)
38	            .await
39	            .expect("axum serve loop");
40	    });
41	    format!("http://{addr}")
42	}
43	
44	/// Boot the actix runtime on an ephemeral loopback port and return its base URL.
45	///
46	/// actix-web owns a non-`Send` per-worker runtime, so — unlike axum — the serve
47	/// loop cannot be a task on the test's runtime. The listener is bound on the
48	/// calling thread, then the serve loop is driven from an `actix_web::rt::System`
49	/// created on a dedicated OS thread. A brief readiness wait lets the accept loop
50	/// come up before the first connection attempt.
51	fn boot_actix() -> String {
52	    let mut builder =
53	        paigasus_helikon_runtime_actix::AgentServer::<()>::builder().with_default_context();
54	    for agent in scripted_agents() {
55	        builder = builder.agent(agent);
56	    }
57	    let server = builder.build().expect("actix server builds");
58	
59	    let listener = std::net::TcpListener::bind("127.0.0.1:0").expect("bind ephemeral port");
60	    let addr = listener.local_addr().expect("local addr");
61	    std::thread::spawn(move || {
62	        actix_web::rt::System::new().block_on(async move {
63	            server
64	                .serve_with_listener(listener)
65	                .await
66	                .expect("actix serve loop");
67	        });
68	    });
69	    std::thread::sleep(std::time::Duration::from_millis(200));
70	    format!("http://{addr}")
71	}
72	
73	/// Replace the run's UUID (read from the body's `run_id` field) with a fixed
74	/// token so two otherwise-identical bodies can be byte-compared. Parsing only
75	/// locates the UUID; the substitution is a raw-text replace, so field order and
76	/// spacing are preserved (a parse-and-reserialize would hide framing drift).
77	fn normalize_run_id(body: &str) -> String {
78	    let value: serde_json::Value = serde_json::from_str(body).expect("run response is JSON");
79	    let run_id = value["run_id"].as_str().expect("run_id is a string");
80	    body.replace(run_id, RUN_ID_TOKEN)
81	}
82	
83	/// Decode the `data:` payloads of an SSE body into a `Vec` of JSON values, in
84	/// order. `event:` tag lines and blank separators are ignored.
85	fn sse_data_values(body: &str) -> Vec<serde_json::Value> {
86	    body.lines()
87	        .filter_map(|line| line.strip_prefix("data:"))
88	        .map(str::trim)
89	        .filter(|data| !data.is_empty())
90	        .map(|data| serde_json::from_str::<serde_json::Value>(data).expect("SSE data is JSON"))
91	        .collect()
92	}
93	
94	/// Order-insensitive canonical form of a JSON array body: each element rendered
95	/// as compact JSON, then sorted. Two `GET /agents` responses are set-equal iff
96	/// their canonical forms match, regardless of HashMap iteration order.
97	fn json_array_set(body: &str) -> Vec<String> {
98	    let value: serde_json::Value = serde_json::from_str(body).expect("body is JSON");
99	    let mut items: Vec<String> = value
100	        .as_array()
101	        .expect("body is a JSON array")
102	        .iter()
103	        .map(|v| serde_json::to_string(v).expect("element re-serializes"))
104	        .collect();
105	    items.sort();
106	    items
107	}
108	
109	/// The full cross-runtime parity sweep. Both servers are booted once with the
110	/// same agent set, then every endpoint in the parity scope is checked.
111	#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
112	async fn axum_and_actix_are_wire_compatible() {
113	    let axum_base = boot_axum().await;
114	    let actix_base = boot_actix();
115	    let client = reqwest::Client::new();
116	
117	    // ── one-shot RunResponse — byte-identical after run_id normalization ──────
118	    {
119	        let axum = client
120	            .post(format!("{axum_base}/agents/echo/runs"))
121	            .header("content-type", "application/json")
122	            .body(r#"{"input":"hi"}"#)
123	            .send()
124	            .await
125	            .expect("axum one-shot request");
126	        let actix = client
127	            .post(format!("{actix_base}/agents/echo/runs"))
128	            .header("content-type", "application/json")
129	            .body(r#"{"input":"hi"}"#)
130	            .send()
131	            .await
132	            .expect("actix one-shot request");
133	
134	        assert_eq!(axum.status(), 200, "axum one-shot status");
135	        assert_eq!(actix.status(), 200, "actix one-shot status");
136	        assert!(
137	            axum.headers().contains_key("x-run-id"),
138	            "axum one-shot sets x-run-id"
139	        );
140	        assert!(
141	            actix.headers().contains_key("x-run-id"),
142	            "actix one-shot sets x-run-id"
143	        );
144	
145	        let axum_body = axum.text().await.expect("axum one-shot body");
146	        let actix_body = actix.text().await.expect("actix one-shot body");
147	
148	        // Content assertions on each runtime independently.
149	        for (name, body) in [("axum", &axum_body), ("actix", &actix_body)] {
150	            let v: serde_json::Value = serde_json::from_str(body).expect("one-shot body is JSON");
151	            assert_eq!(v["status"], "completed", "{name} one-shot status field");
152	            assert_eq!(v["output"], "echo", "{name} one-shot output field");
153	        }
154	
155	        assert_eq!(
156	            normalize_run_id(&axum_body),
157	            normalize_run_id(&actix_body),
158	            "one-shot RunResponse bodies must be byte-identical after run_id normalization\n\
159	             axum : {axum_body}\nactix: {actix_body}"
160	        );
161	    }
162	
163	    // ── SSE — Content-Type + decoded events + RAW BYTE parity ────────────────
164	    {
165	        let axum = client
166	            .post(format!("{axum_base}/agents/echo/runs?stream=sse"))
167	            .header("content-type", "application/json")
168	            .body(r#"{"input":"hi"}"#)
169	            .send()
170	            .await
171	            .expect("axum sse request");
172	        let actix = client
173	            .post(format!("{actix_base}/agents/echo/runs?stream=sse"))
174	            .header("content-type", "application/json")
175	            .body(r#"{"input":"hi"}"#)
176	            .send()
177	            .await
178	            .expect("actix sse request");
179	
180	        assert_eq!(axum.status(), 200, "axum sse status");
181	        assert_eq!(actix.status(), 200, "actix sse status");
182	        let content_type = |resp: &reqwest::Response| -> String {
183	            resp.headers()
184	                .get(reqwest::header::CONTENT_TYPE)
185	                .and_then(|v| v.to_str().ok())
186	                .expect("sse content-type header")
187	                .to_owned()
188	        };
189	        assert_eq!(
190	            content_type(&axum),
191	            "text/event-stream",
192	            "axum sse content-type"
193	        );
194	        assert_eq!(
195	            content_type(&actix),
196	            "text/event-stream",
197	            "actix sse content-type"
198	        );
199	
200	        let axum_bytes = axum.bytes().await.expect("axum sse body");
201	        let actix_bytes = actix.bytes().await.expect("actix sse body");
202	
203	        // Decoded event-sequence parity (semantic).
204	        let axum_text = String::from_utf8(axum_bytes.to_vec()).expect("axum sse is utf-8");
205	        let actix_text = String::from_utf8(actix_bytes.to_vec()).expect("actix sse is utf-8");
206	        assert_eq!(
207	            sse_data_values(&axum_text),
208	            sse_data_values(&actix_text),
209	            "SSE decoded event sequences must match"
210	        );
211	
212	        // The key check: SSE frames carry no run_id, so the raw bytes must match
213	        // exactly. axum's `to_sse_event` and actix's hand-rolled `sse_frame` are
214	        // meant to produce identical `event: <tag>\ndata: <json>\n\n` frames.
215	        assert_eq!(
216	            axum_bytes, actix_bytes,
217	            "SSE raw bodies must be byte-identical\naxum : {axum_text:?}\nactix: {actix_text:?}"
218	        );
219	    }
220	
221	    // ── GET /agents — set-equal (order-insensitive) ──────────────────────────
222	    {
223	        let axum_body = client
224	            .get(format!("{axum_base}/agents"))
225	            .send()
226	            .await
227	            .expect("axum GET /agents")
228	            .text()
229	            .await
230	            .expect("axum /agents body");
231	        let actix_body = client
232	            .get(format!("{actix_base}/agents"))
233	            .send()
234	            .await
235	            .expect("actix GET /agents")
236	            .text()
237	            .await
238	            .expect("actix /agents body");
239	
240	        assert_eq!(
241	            json_array_set(&axum_body),
242	            json_array_set(&actix_body),
243	            "GET /agents must be set-equal\naxum : {axum_body}\nactix: {actix_body}"
244	        );
245	    }
246	
247	    // ── async ?mode=async — 202 + string run_id ──────────────────────────────
248	    {
249	        for (name, base) in [("axum", &axum_base), ("actix", &actix_base)] {
250	            let resp = client
251	                .post(format!("{base}/agents/echo/runs?mode=async"))
252	                .header("content-type", "application/json")
253	                .body(r#"{"input":"hi"}"#)
254	                .send()
255	                .await
256	                .unwrap_or_else(|e| panic!("{name} async request: {e}"));
257	            assert_eq!(resp.status(), 202, "{name} async status");
258	            let v: serde_json::Value = resp.json().await.expect("async body is JSON");
259	            assert!(
260	                v["run_id"].as_str().is_some(),
261	                "{name} async response carries a string run_id: {v}"
262	            );
263	        }
264	    }
265	
266	    // ── content-type is case-insensitive (RFC 9110 §8.3.1) ───────────────────
267	    {
268	        for (name, base) in [("axum", &axum_base), ("actix", &actix_base)] {
269	            for ct in ["Application/JSON", "APPLICATION/JSON; charset=UTF-8"] {
270	                let resp = client
271	                    .post(format!("{base}/agents/echo/runs?mode=async"))
272	                    .header("content-type", ct)
273	                    .body(r#"{"input":"hi"}"#)
274	                    .send()
275	                    .await
276	                    .unwrap_or_else(|e| panic!("{name} request with `{ct}`: {e}"));
277	                assert_eq!(
278	                    resp.status(),
279	                    202,
280	                    "{name} must accept `{ct}` — media types are case-insensitive"
281	                );
282	            }
283	        }
284	    }
285	
286	    // ── error body — 404 + byte-identical {"error":...} ──────────────────────
287	    {
288	        let axum_resp = client
289	            .post(format!("{axum_base}/agents/does-not-exist/runs"))
290	            .header("content-type", "application/json")
291	            .body(r#"{"input":"hi"}"#)
292	            .send()
293	            .await
294	            .expect("axum unknown-agent request");
295	        let actix_resp = client
296	            .post(format!("{actix_base}/agents/does-not-exist/runs"))
297	            .header("content-type", "application/json")
298	            .body(r#"{"input":"hi"}"#)
299	            .send()
300	            .await
301	            .expect("actix unknown-agent request");
302	
303	        assert_eq!(axum_resp.status(), 404, "axum unknown-agent status");
304	        assert_eq!(actix_resp.status(), 404, "actix unknown-agent status");
305	
306	        let axum_body = axum_resp.text().await.expect("axum error body");
307	        let actix_body = actix_resp.text().await.expect("actix error body");
308	        assert_eq!(
309	            axum_body, actix_body,
310	            "404 error bodies must be byte-identical\naxum : {axum_body}\nactix: {actix_body}"
311	        );
312	    }
313	
314	    // ── /openapi.json — structural: 200 + the three documented paths ─────────
315	    {
316	        for (name, base) in [("axum", &axum_base), ("actix", &actix_base)] {
317	            let resp = client
318	                .get(format!("{base}/openapi.json"))
319	                .send()
320	                .await
321	                .unwrap_or_else(|e| panic!("{name} openapi request: {e}"));
322	            assert_eq!(resp.status(), 200, "{name} openapi status");
323	            let spec: serde_json::Value = resp.json().await.expect("openapi body is JSON");
324	            let paths = spec["paths"]
325	                .as_object()
326	                .unwrap_or_else(|| panic!("{name} openapi document has a `paths` object: {spec}"));
327	            for expected in [
328	                "/agents",
329	                "/agents/{name}/runs",
330	                "/agents/{name}/runs/{id}/events",
331	            ] {
332	                assert!(
333	                    paths.contains_key(expected),
334	                    "{name} openapi paths missing `{expected}`; got keys {:?}",
335	                    paths.keys().collect::<Vec<_>>()
336	                );
337	            }
338	        }
339	    }
340	}
