1	//! Request-level authentication middleware for the actix runtime.
2	//!
3	//! [`AuthGuard`] is a hand-rolled actix-web [`Transform`]/[`Service`] pair that
4	//! gates **every** wrapped route behind an [`AuthLayer`], matching the axum
5	//! runtime's router-level gate. It is installed by
6	//! [`AgentServer::configure`](crate::AgentServer::configure) only when an
7	//! [`AuthLayer`] is configured; otherwise the scope is registered unwrapped and
8	//! no authentication runs.
9	//!
10	//! # Flow
11	//!
12	//! On each [`ServiceRequest`] the guard calls
13	//! [`AuthLayer::authenticate`](crate::AuthLayer::authenticate) with the shared
14	//! [`HttpRequest`](actix_web::HttpRequest):
15	//!
16	//! - on `Err(rejection)` it short-circuits with the JSON error response from
17	//!   [`ServerError::Unauthorized`], and the wrapped service never runs;
18	//! - on `Ok(())` it forwards to the wrapped service unchanged.
19	//!
20	//! Any identity the auth layer inserts into `req.extensions_mut()` survives to
21	//! the handler, because the `ServiceRequest` and the handler's `HttpRequest`
22	//! share one `RefCell<Extensions>` — this is the documented auth→context bridge.
23	//!
24	//! # `!Send` futures
25	//!
26	//! [`AuthLayer`] is `#[async_trait(?Send)]`, so its future is not required to be
27	//! `Send`; the guard's `call` future is `Pin<Box<dyn Future>>` (no `Send`
28	//! bound), which actix polls to completion on the worker thread that received
29	//! the request. This mirrors actix-web's request-bound execution model.
30	
31	use std::{
32	    future::{ready, Future, Ready},
33	    pin::Pin,
34	    rc::Rc,
35	    sync::Arc,
36	};
37	
38	use actix_web::{
39	    body::EitherBody,
40	    dev::{forward_ready, Service, ServiceRequest, ServiceResponse, Transform},
41	    Error, ResponseError,
42	};
43	
44	use crate::{auth::AuthLayer, error::ServerError};
45	
46	/// Middleware factory that gates every wrapped route behind an [`AuthLayer`].
47	///
48	/// Wrap a scope with `.wrap(AuthGuard::new(auth))` to require authentication on
49	/// all of its routes.
50	pub(crate) struct AuthGuard {
51	    auth: Arc<dyn AuthLayer>,
52	}
53	
54	impl AuthGuard {
55	    /// Construct a guard that delegates authentication to `auth`.
56	    pub(crate) fn new(auth: Arc<dyn AuthLayer>) -> Self {
57	        Self { auth }
58	    }
59	}
60	
61	impl<S, B> Transform<S, ServiceRequest> for AuthGuard
62	where
63	    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
64	    B: 'static,
65	{
66	    type Response = ServiceResponse<EitherBody<B>>;
67	    type Error = Error;
68	    type Transform = AuthGuardService<S>;
69	    type InitError = ();
70	    type Future = Ready<Result<Self::Transform, Self::InitError>>;
71	
72	    fn new_transform(&self, service: S) -> Self::Future {
73	        ready(Ok(AuthGuardService {
74	            service: Rc::new(service),
75	            auth: Arc::clone(&self.auth),
76	        }))
77	    }
78	}
79	
80	/// The [`Service`] produced by [`AuthGuard`]; authenticates each request before
81	/// forwarding it to the wrapped `service`.
82	pub(crate) struct AuthGuardService<S> {
83	    service: Rc<S>,
84	    auth: Arc<dyn AuthLayer>,
85	}
86	
87	impl<S, B> Service<ServiceRequest> for AuthGuardService<S>
88	where
89	    S: Service<ServiceRequest, Response = ServiceResponse<B>, Error = Error> + 'static,
90	    B: 'static,
91	{
92	    type Response = ServiceResponse<EitherBody<B>>;
93	    type Error = Error;
94	    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>>>>;
95	
96	    forward_ready!(service);
97	
98	    fn call(&self, req: ServiceRequest) -> Self::Future {
99	        let service = Rc::clone(&self.service);
100	        let auth = Arc::clone(&self.auth);
101	        Box::pin(async move {
102	            // The `&HttpRequest` borrow ends before `req` is moved into
